const status=document.createElement('div');status.id='observer-auto';status.setAttribute('role','status');status.innerHTML='<span>✧ OBSERVER ACTIVE</span><small>Learning how you play</small>';document.body.append(status);
let busy=false,lastCall=0,lastChamber=0,lastFalls=0,active=0,lastProgress='',stalled=0,completedChecked=false;
function label(title,detail){status.querySelector('span').textContent='✧ '+title;status.querySelector('small').textContent=detail;}
async function adapt(reason,state){if(busy)return;busy=true;lastCall=Date.now();label('OBSERVER THINKING','Reading your progress');try{const r=await fetch('/api/observer',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:'adapt',question:reason,state}),signal:AbortSignal.timeout(55000)});const data=await r.json();if(!r.ok)throw new Error(data.error);const decision=JSON.parse(data.text.replace(/^```(?:json)?\s*|\s*```$/g,''));if(window.parallaxObserver.read().chamber!==state.chamber)return;const applied=window.parallaxObserver.adapt(decision,state);label(applied.title,applied.detail);}catch{label('OBSERVER RECONNECTING','Difficulty unchanged · keep exploring');}finally{busy=false;}}
setInterval(()=>{if(!window.parallaxObserver||document.hidden)return;const state=window.parallaxObserver.read();if(state.chamber!==lastChamber){lastChamber=state.chamber;active=0;stalled=0;lastFalls=0;lastProgress='';completedChecked=false;label('OBSERVER ACTIVE','Learning how you play');}const progress=`${state.fragments}:${state.position.x}:${state.position.z}:${state.reality}`;if(progress!==lastProgress){lastProgress=progress;stalled=0;}else stalled+=2;if(!state.moving&&!document.querySelector('#help-dialog[open],#chambers-dialog[open]'))active+=2;state.activeSeconds=active;
if(state.completed&&!completedChecked){completedChecked=true;adapt('Chamber completed. Decide whether the next challenge can be harder.',state);return;}if(busy||state.moving||Date.now()-lastCall<25000)return;if(state.falls>=lastFalls+2){lastFalls=state.falls;adapt('Repeated falls. Consider safety assistance.',state);}else if(stalled>=50&&active>=50){stalled=0;adapt('No movement or fragment progress recently. Time alone is not evidence of confusion; choose continue unless other evidence supports help.',state);}},2000);
